using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using EfFixtures;

public sealed record BlogViews(int BlogId, int TotalViews);

public static class BlogQueries
{
    public static async Task<List<BlogViews>> GetTotalViewsByBlogAsync(
        BlogContext context,
        string searchTerm,
        CancellationToken cancellationToken)
    {
        var query =
            from post in context.Posts
            where post.Title.Contains(searchTerm)
            group post by post.BlogId into posts
            select new BlogViews(
                posts.Key,
                posts.Sum(post => post.Views));

        var results = await query.ToListAsync(cancellationToken);
        return results;
    }
}
